// pnpm add --save-dev prisma dotenv
import { existsSync } from 'node:fs';
import { loadEnvFile } from 'node:process';
import { defineConfig } from 'prisma/config';

// This config is also copied into Docker build and migration images without src/.
if (
  process.env.NODE_ENV !== 'production' &&
  process.env.NODE_ENV !== 'test' &&
  existsSync('.env.development')
) {
  loadEnvFile('.env.development');
}

export default defineConfig({
  schema: 'prisma/schema.prisma',
  migrations: {
    path: 'prisma/migrations',
  },
  datasource: {
    // Prisma CLI debe usar la conexión directa de Neon para migraciones.
    // El backend conserva DATABASE_URL (agrupada) en tiempo de ejecución.
    url: process.env['DIRECT_URL'] ?? process.env['DATABASE_URL'],
  },
});
